{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 자전거 안전교육 인증으로 따릉이(공공자전거) 이용요금 할인 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 자전거 안전교육 인증을 받은 사람은 공공자전거 이용요금의 일부 또는 전부를 감면받을 수 있는 대상에 해당한다. 조례 제12조의3제1항은 시장이 공공자전거 이용 시민 등을 대상으로 이용요금의 일부 또는 전부를 감면할 수 있다고 정하고, 같은 조 제2항제6호는 제13조제6항에 따른 자전거 교통안전교육 인증을 받은 사람을 감면 대상자로 규정한다. 따라서 자전거 안전교육 인증을 받으면 따릉이(공공자전거) 할인 대상이 될 수 있다.",
          "b_ids": "자전거:제12조의3제1항, 자전거:제12조의3제2항제6호, 자전거:제13조제6항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
